#include <string>
using namespace std;

// Whether a ride is willing to share a driver with another rider.
enum class RideType { SOLO, POOLED };

// Lifecycle status of a single ride.
enum class RideStatus { REQUESTED, MATCHED, COMPLETED };

// A courier with a location, a capacity, and the active route of whoever they picked up first.
class Driver {
public:
    string driverId;        // unique id
    double locationX;          // base x coordinate
    double locationY;             // base y coordinate
    int capacity;                    // max concurrent riders this driver can carry
    int currentRiders;                  // riders currently on board
    double activePickupX;                  // reference route: first rider's pickup x
    double activePickupY;                     // reference route: first rider's pickup y
    double activeDropoffX;                       // reference route: first rider's dropoff x
    double activeDropoffY;                          // reference route: first rider's dropoff y

    Driver() : locationX(0.0), locationY(0.0), capacity(0), currentRiders(0),
               activePickupX(0.0), activePickupY(0.0), activeDropoffX(0.0), activeDropoffY(0.0) {}
    Driver(string id, double x, double y, int cap)
        : driverId(id), locationX(x), locationY(y), capacity(cap), currentRiders(0),
          activePickupX(0.0), activePickupY(0.0), activeDropoffX(0.0), activeDropoffY(0.0) {}
    // constructor stores id, base location, and capacity, starting empty

    bool isEmpty() { return currentRiders == 0; }              // true if carrying nobody
    bool hasSpareSeat() { return currentRiders < capacity; }      // true if room for one more

    void assignFresh(double pickupX, double pickupY, double dropoffX, double dropoffY) {
        activePickupX = pickupX;     // this becomes the reference route's pickup
        activePickupY = pickupY;       // ...
        activeDropoffX = dropoffX;       // and its dropoff
        activeDropoffY = dropoffY;          // ...
        currentRiders = 1;                     // now carrying one rider
    }

    void addPooledRider() { currentRiders++; } // a second rider joins the existing reference route
    void removeRider() { currentRiders--; }       // a rider's trip completes, freeing a seat
};

// One rider's trip request, tracked through its lifecycle.
class Ride {
public:
    string rideId;              // unique id, e.g. RIDE1
    string riderName;              // who requested it
    double pickupX;                   // pickup x coordinate
    double pickupY;                      // pickup y coordinate
    double dropoffX;                        // dropoff x coordinate
    double dropoffY;                           // dropoff y coordinate
    RideType type;                                // solo or pooled
    string assignedDriverId;                         // which driver is carrying it, if any
    RideStatus status;                                  // current lifecycle state

    Ride() : pickupX(0.0), pickupY(0.0), dropoffX(0.0), dropoffY(0.0), type(RideType::SOLO), status(RideStatus::REQUESTED) {}
    Ride(string id, string rider, double pX, double pY, double dX, double dY, RideType t)
        : rideId(id), riderName(rider), pickupX(pX), pickupY(pY), dropoffX(dX), dropoffY(dY), type(t), status(RideStatus::REQUESTED) {}
    // constructor stores every field and starts the ride as REQUESTED
};

// Creates sequential, correctly-prefixed ids for rides.
class RideIdFactory {
    int rideCounter = 0; // running id counter

public:
    string nextRideId() {
        rideCounter++;                    // bump id counter
        return "RIDE" + to_string(rideCounter); // e.g. RIDE1
    }
};

