// Reusable straight line distance helper.
class DistanceUtil {
    public static double distance(double x1, double y1, double x2, double y2) {
        double dx = x2-x1;               // x difference
        double dy = y2-y1;                  // y difference
        return Math.sqrt(dx * dx + dy * dy);  // Euclidean distance
    }
}

// Strategy interface: how a driver is chosen for a ride request.
interface MatchingStrategy {
    Driver findDriver(Ride ride, java.util.Collection<Driver> drivers); // returns the chosen driver, or null if none qualifies
}

// Only matches empty drivers, never shares a ride, choosing the nearest one to the pickup.
class DirectMatchingStrategy implements MatchingStrategy {
    @Override
    public Driver findDriver(Ride ride, java.util.Collection<Driver> drivers) {
        Driver best = null;                                                    // best empty candidate found so far
        double bestDistance = Double.MAX_VALUE;                                    // distance of the best candidate
        for (Driver driver : drivers) {                                               // scan every registered driver
            if (!driver.isEmpty()) continue;                                             // solo never shares, skip occupied drivers
            double distance = DistanceUtil.distance(driver.getLocationX(), driver.getLocationY(), ride.getPickupX(), ride.getPickupY());
            if (distance < bestDistance) {                                                   // closer than anything seen so far
                bestDistance = distance;                                                        // remember the new best distance
                best = driver;                                                                    // remember the new best driver
            }
        }
        return best; // the nearest empty driver, or null if none exist
    }
}

// Tries a detour constrained insertion into an occupied driver first, falls back to the nearest empty driver.
class PooledMatchingStrategy implements MatchingStrategy {
    private final double maxDetourDistance; // how much extra distance a pooling insertion may add

    public PooledMatchingStrategy(double maxDetourDistance) {
        this.maxDetourDistance = maxDetourDistance; // store the detour tolerance
    }

    // Computes the extra distance inserting this ride into the driver's existing route would add.
    public double computeDetour(Driver driver, Ride ride) {
        double originalDistance = DistanceUtil.distance(driver.getActivePickupX(), driver.getActivePickupY(), driver.getActiveDropoffX(), driver.getActiveDropoffY());
        double toNewPickup = DistanceUtil.distance(driver.getActivePickupX(), driver.getActivePickupY(), ride.getPickupX(), ride.getPickupY());
        double acrossNewRide = DistanceUtil.distance(ride.getPickupX(), ride.getPickupY(), ride.getDropoffX(), ride.getDropoffY());
        double toOriginalDropoff = DistanceUtil.distance(ride.getDropoffX(), ride.getDropoffY(), driver.getActiveDropoffX(), driver.getActiveDropoffY());
        double newDistance = toNewPickup + acrossNewRide + toOriginalDropoff; // full route with the insertion
        return newDistance-originalDistance; // the extra distance this insertion would add
    }

    @Override
    public Driver findDriver(Ride ride, java.util.Collection<Driver> drivers) {
        Driver bestPoolCandidate = null;                                          // best occupied candidate found so far
        double bestDetour = Double.MAX_VALUE;                                        // detour of the best candidate
        for (Driver driver : drivers) {                                                 // scan every registered driver
            if (driver.isEmpty() || !driver.hasSpareSeat()) continue;                      // only consider occupied drivers with room
            double detour = computeDetour(driver, ride);                                     // extra distance this insertion would add
            if (detour <= maxDetourDistance && detour < bestDetour) {                           // within tolerance and better than seen so far
                bestDetour = detour;                                                               // remember the new best detour
                bestPoolCandidate = driver;                                                           // remember the new best pool candidate
            }
        }
        if (bestPoolCandidate != null) return bestPoolCandidate; // a pooling opportunity qualified
        return new DirectMatchingStrategy().findDriver(ride, drivers); // otherwise fall back to the nearest empty driver
    }
}

// Observer interface: reacts to ride lifecycle events.
interface RideObserver {
    void onRideMatched(Ride ride, Driver driver);         // a ride was successfully matched
    void onMatchFailed(String rideId, String reason);        // a match attempt found no driver
    void onRideCompleted(Ride ride);                            // a ride finished
}

// Simple observer that prints events to the console.
class ConsoleRideObserver implements RideObserver {
    @Override
    public void onRideMatched(Ride ride, Driver driver) {
        System.out.println("Ride " + ride.getRideId() + " matched to " + driver.getDriverId() + ", riders now " + driver.getCurrentRiders());
    }

    @Override
    public void onMatchFailed(String rideId, String reason) {
        System.out.println("Match failed for " + rideId + ": " + reason);
    }

    @Override
    public void onRideCompleted(Ride ride) {
        System.out.println("Ride " + ride.getRideId() + " completed");
    }
}

