// Custom exceptions for the realistic failure modes.
class NoDriverAvailableException extends RuntimeException {
    public NoDriverAvailableException(String msg) { super(msg); }
}
class InvalidRideStateException extends RuntimeException {
    public InvalidRideStateException(String msg) { super(msg); }
}
class DetourLimitExceededException extends RuntimeException {
    public DetourLimitExceededException(String msg) { super(msg); }
}

// The core ride matching engine tying every piece together.
class RideDispatchService {
    private static final double BASE_FARE = 5.0;                                                     // flat fare component
    private static final double PER_KM_RATE = 2.0;                                                       // distance based fare component
    private static final double POOL_DISCOUNT = 0.8;                                                        // multiplier applied when a ride ends up shared
    private final java.util.Map<String, Driver> drivers = new java.util.HashMap<>();                          // driverId -> Driver
    private final java.util.Map<String, Ride> rides = new java.util.HashMap<>();                                 // rideId -> Ride
    private final PooledMatchingStrategy pooledMatchingStrategy;                                                    // shared instance, so its detour limit is reused
    private final java.util.List<RideObserver> observers = new java.util.ArrayList<>();                               // listeners

    public RideDispatchService(double maxDetourDistance) {
        this.pooledMatchingStrategy = new PooledMatchingStrategy(maxDetourDistance); // configure the detour tolerance once
    }

    public void addDriver(Driver driver) { drivers.put(driver.getDriverId(), driver); } // register a driver
    public void addObserver(RideObserver observer) { observers.add(observer); }            // register a listener

    private MatchingStrategy strategyFor(RideType type) {
        return type == RideType.SOLO ? new DirectMatchingStrategy() : pooledMatchingStrategy; // solo never pools, pooled tries to
    }

    // Matches a new ride request using the strategy appropriate to its type.
    public synchronized Ride requestRide(String riderName, double pickupX, double pickupY, double dropoffX, double dropoffY, RideType type, RideIdFactory factory) {
        String rideId = factory.nextRideId();                                             // build id
        Ride ride = new Ride(rideId, riderName, pickupX, pickupY, dropoffX, dropoffY, type);  // build the ride
        rides.put(rideId, ride);                                                               // register it
        MatchingStrategy strategy = strategyFor(type);                                           // pick the matching algorithm for this type
        Driver driver = strategy.findDriver(ride, drivers.values());                               // ask it for a driver
        if (driver == null) {                                                                        // nobody qualifies
            for (RideObserver obs : observers) obs.onMatchFailed(rideId, "No driver available");
            throw new NoDriverAvailableException("No driver available for ride " + rideId);
        }
        if (driver.isEmpty()) driver.assignFresh(pickupX, pickupY, dropoffX, dropoffY); // this driver's first rider defines the reference route
        else driver.addPooledRider();                                                     // otherwise this rider joins the existing reference route
        ride.setAssignedDriverId(driver.getDriverId());                                     // record the assignment
        ride.setStatus(RideStatus.MATCHED);                                                   // advance the lifecycle
        for (RideObserver obs : observers) obs.onRideMatched(ride, driver);                      // notify
        return ride; // hand back the now-matched ride
    }

    // Directly attempts to pool a ride onto a specific driver, still detour-checked.
    public synchronized Ride poolManually(String rideId, String driverId, RideIdFactory factory) {
        Ride ride = rides.get(rideId);                                                // the ride to pool
        Driver driver = drivers.get(driverId);                                           // the requested driver
        if (driver.isEmpty() || !driver.hasSpareSeat()) {                                   // must already be occupied with room, or this is not a pooling case
            throw new DetourLimitExceededException("Driver " + driverId + " is not a valid pooling target");
        }
        double detour = pooledMatchingStrategy.computeDetour(driver, ride);                    // extra distance this insertion would add
        if (detour > pooledMatchingStrategy.maxDetourDistance) {
            throw new DetourLimitExceededException("Pooling onto " + driverId + " would add a detour of " + detour);
        }
        driver.addPooledRider();                                                                 // this rider joins the existing reference route
        ride.setAssignedDriverId(driverId);                                                         // record the assignment
        ride.setStatus(RideStatus.MATCHED);                                                           // advance the lifecycle
        for (RideObserver obs : observers) obs.onRideMatched(ride, driver);                              // notify
        return ride; // hand back the now-matched ride
    }

    // Computes the price for a ride, applying the pooled discount if the ride's driver currently carries more than one rider.
    public double calculateFare(String rideId) {
        Ride ride = rides.get(rideId);                                                    // the ride to price
        Driver driver = drivers.get(ride.getAssignedDriverId());                              // its assigned driver
        double distance = DistanceUtil.distance(ride.getPickupX(), ride.getPickupY(), ride.getDropoffX(), ride.getDropoffY()); // direct trip distance
        double fare = BASE_FARE + PER_KM_RATE * distance;                                         // base plus distance based component
        if (driver.getCurrentRiders() > 1) fare *= POOL_DISCOUNT;                                     // apply the pooled discount if actually shared
        return fare; // the computed price
    }

    // Transitions a matched ride to completed, freeing its driver's occupied seat.
    public Ride completeRide(String rideId) {
        Ride ride = rides.get(rideId);                                        // the ride to complete
        if (ride.getStatus() != RideStatus.MATCHED) {                            // must currently be matched
            throw new InvalidRideStateException("Ride " + rideId + " is not matched, cannot be completed");
        }
        Driver driver = drivers.get(ride.getAssignedDriverId());                    // its assigned driver
        driver.removeRider();                                                          // free up their seat
        ride.setStatus(RideStatus.COMPLETED);                                            // advance the lifecycle
        for (RideObserver obs : observers) obs.onRideCompleted(ride);                       // notify
        return ride; // hand back the updated ride
    }
}

