#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class NoDriverAvailableException : public runtime_error {
public: NoDriverAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidRideStateException : public runtime_error {
public: InvalidRideStateException(const string& msg) : runtime_error(msg) {}
};
class DetourLimitExceededException : public runtime_error {
public: DetourLimitExceededException(const string& msg) : runtime_error(msg) {}
};

// The core ride matching engine tying every piece together.
class RideDispatchService {
    static constexpr double BASE_FARE = 5.0;             // flat fare component
    static constexpr double PER_KM_RATE = 2.0;              // distance based fare component
    static constexpr double POOL_DISCOUNT = 0.8;               // multiplier applied when a ride ends up shared
    map<string, Driver> drivers;                                  // driverId -> Driver
    map<string, Ride> rides;                                         // rideId -> Ride
    PooledMatchingStrategy pooledMatchingStrategy;                      // shared instance, so its detour limit is reused
    vector<shared_ptr<RideObserver>> observers;                            // listeners

    shared_ptr<MatchingStrategy> strategyFor(RideType type) {
        if (type == RideType::SOLO) return make_shared<DirectMatchingStrategy>(); // solo never pools
        return shared_ptr<MatchingStrategy>(&pooledMatchingStrategy, [](MatchingStrategy*){}); // pooled reuses the shared instance, no-op deleter since it is not heap owned
    }

public:
    RideDispatchService(double maxDetourDistance) : pooledMatchingStrategy(maxDetourDistance) {} // configure the detour tolerance once

    void addDriver(Driver driver) { drivers[driver.driverId] = driver; }        // register a driver
    void addObserver(shared_ptr<RideObserver> observer) { observers.push_back(observer); } // register a listener

    Ride requestRide(string riderName, double pickupX, double pickupY, double dropoffX, double dropoffY, RideType type, RideIdFactory& factory) {
        string rideId = factory.nextRideId();                                                // build id
        Ride ride(rideId, riderName, pickupX, pickupY, dropoffX, dropoffY, type);               // build the ride
        rides[rideId] = ride;                                                                      // register it
        auto strategy = strategyFor(type);                                                           // pick the matching algorithm for this type
        vector<Driver*> pointers;                                                                        // strategy needs pointers so it can mutate occupancy
        for (auto& pair : drivers) pointers.push_back(&pair.second);                                        // collect every registered driver
        Driver* driver = strategy->findDriver(ride, pointers);                                                // ask it for a driver
        if (driver == nullptr) {                                                                                // nobody qualifies
            for (auto& obs : observers) obs->onMatchFailed(rideId, "No driver available");
            throw NoDriverAvailableException("No driver available for ride " + rideId);
        }
        if (driver->isEmpty()) driver->assignFresh(pickupX, pickupY, dropoffX, dropoffY); // this driver's first rider defines the reference route
        else driver->addPooledRider();                                                      // otherwise this rider joins the existing reference route
        Ride& storedRide = rides.at(rideId);                                                  // work against the stored copy
        storedRide.assignedDriverId = driver->driverId;                                          // record the assignment
        storedRide.status = RideStatus::MATCHED;                                                    // advance the lifecycle
        for (auto& obs : observers) obs->onRideMatched(storedRide, *driver);                           // notify
        return storedRide; // hand back the now-matched ride
    }

    Ride poolManually(string rideId, string driverId, RideIdFactory& factory) {
        Ride& ride = rides.at(rideId);                                                // the ride to pool
        Driver& driver = drivers.at(driverId);                                           // the requested driver
        if (driver.isEmpty() || !driver.hasSpareSeat()) {                                   // must already be occupied with room, or this is not a pooling case
            throw DetourLimitExceededException("Driver " + driverId + " is not a valid pooling target");
        }
        double detour = pooledMatchingStrategy.computeDetour(driver, ride);                    // extra distance this insertion would add
        if (detour > pooledMatchingStrategy.getMaxDetourDistance()) {
            throw DetourLimitExceededException("Pooling onto " + driverId + " would add a detour of " + to_string(detour));
        }
        driver.addPooledRider();                                                                 // this rider joins the existing reference route
        ride.assignedDriverId = driverId;                                                           // record the assignment
        ride.status = RideStatus::MATCHED;                                                            // advance the lifecycle
        for (auto& obs : observers) obs->onRideMatched(ride, driver);                                    // notify
        return ride; // hand back the now-matched ride
    }

    double calculateFare(string rideId) {
        Ride& ride = rides.at(rideId);                                                    // the ride to price
        Driver& driver = drivers.at(ride.assignedDriverId);                                   // its assigned driver
        double tripDistance = distanceBetween(ride.pickupX, ride.pickupY, ride.dropoffX, ride.dropoffY); // direct trip distance
        double fare = BASE_FARE + PER_KM_RATE * tripDistance;                                       // base plus distance based component
        if (driver.currentRiders > 1) fare *= POOL_DISCOUNT;                                            // apply the pooled discount if actually shared
        return fare; // the computed price
    }

    Ride completeRide(string rideId) {
        Ride& ride = rides.at(rideId);                                        // the ride to complete
        if (ride.status != RideStatus::MATCHED) {                                // must currently be matched
            throw InvalidRideStateException("Ride " + rideId + " is not matched, cannot be completed");
        }
        Driver& driver = drivers.at(ride.assignedDriverId);                        // its assigned driver
        driver.removeRider();                                                         // free up their seat
        ride.status = RideStatus::COMPLETED;                                             // advance the lifecycle
        for (auto& obs : observers) obs->onRideCompleted(ride);                             // notify
        return ride; // hand back the updated ride
    }
};

