public class Main {
    public static void main(String[] args) {
        RideDispatchService service = new RideDispatchService(3.0);
        service.addObserver(new ConsoleRideObserver());
        RideIdFactory factory = new RideIdFactory();

        Driver d1 = new Driver("D1", 0.0, 0.0, 2);
        Driver d2 = new Driver("D2", 10.0, 10.0, 2);
        service.addDriver(d1);
        service.addDriver(d2);

        Ride alice = service.requestRide("Alice", 1.0, 1.0, 3.0, 3.0, RideType.POOLED, factory);
        Ride bob = service.requestRide("Bob", 2.0, 2.0, 4.0, 2.0, RideType.POOLED, factory);
        Ride carol = service.requestRide("Carol", 11.0, 11.0, 13.0, 13.0, RideType.POOLED, factory);

        try {
            service.requestRide("Dave", 10.5, 10.5, 12.0, 12.0, RideType.SOLO, factory);
        } catch (NoDriverAvailableException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        System.out.println("Alice fare: " + service.calculateFare(alice.getRideId()));
        System.out.println("Bob fare: " + service.calculateFare(bob.getRideId()));
        System.out.println("Carol fare: " + service.calculateFare(carol.getRideId()));

        Driver d3 = new Driver("D3", 50.0, 50.0, 2);
        service.addDriver(d3);

        Ride eve = service.requestRide("Eve", 50.0, 50.0, 60.0, 60.0, RideType.POOLED, factory);
        try {
            service.poolManually(eve.getRideId(), "D2", factory);
        } catch (DetourLimitExceededException e) {
            System.out.println("Caught expected: detour limit exceeded");
        }

        service.completeRide(alice.getRideId());
    }
}

