        this.driverId = driverId;
        this.locationX = locationX;
        this.locationY = locationY;
        this.capacity = capacity;
        this.currentRiders = 0;
    }

    public String getDriverId() { return driverId; }
    public double getLocationX() { return locationX; }
    public double getLocationY() { return locationY; }
    public int getCapacity() { return capacity; }
    public int getCurrentRiders() { return currentRiders; }
    public boolean isEmpty() { return currentRiders == 0; }
    public boolean hasSpareSeat() { return currentRiders < capacity; }
    public double getActivePickupX() { return activePickupX; }
    public double getActivePickupY() { return activePickupY; }
    public double getActiveDropoffX() { return activeDropoffX; }
    public double getActiveDropoffY() { return activeDropoffY; }

