            throw new DetourLimitExceededException("Pooling onto " + driverId + " would add a detour of " + detour);
        }
        driver.addPooledRider();
        ride.setAssignedDriverId(driverId);
        ride.setStatus(RideStatus.MATCHED);
        for (RideObserver obs : observers) obs.onRideMatched(ride, driver);
        return ride;
    }

