        Ride ride = rides.get(rideId);
        Driver driver = drivers.get(ride.getAssignedDriverId());
        double distance = DistanceUtil.distance(ride.getPickupX(), ride.getPickupY(), ride.getDropoffX(), ride.getDropoffY());
        double fare = BASE_FARE + PER_KM_RATE * distance;
