        }
        Driver driver = drivers.get(ride.getAssignedDriverId());
        driver.removeRider();
        ride.setStatus(RideStatus.COMPLETED);
        for (RideObserver obs : observers) obs.onRideCompleted(ride);
        return ride;
    }
}

