            throw NoDriverAvailableException("No driver available for ride " + rideId);
        }
        if (driver->isEmpty()) driver->assignFresh(pickupX, pickupY, dropoffX, dropoffY);
        else driver->addPooledRider();
        Ride& storedRide = rides.at(rideId);
        storedRide.assignedDriverId = driver->driverId;
        storedRide.status = RideStatus::MATCHED;
        for (auto& obs : observers) obs->onRideMatched(storedRide, *driver);
        return storedRide;
    }

    Ride poolManually(string rideId, string driverId, RideIdFactory& factory) {
        Ride& ride = rides.at(rideId);
        Driver& driver = drivers.at(driverId);
        if (driver.isEmpty() || !driver.hasSpareSeat()) {
            throw DetourLimitExceededException("Driver " + driverId + " is not a valid pooling target");
        }
        double detour = pooledMatchingStrategy.computeDetour(driver, ride);
        if (detour > pooledMatchingStrategy.getMaxDetourDistance()) {
            throw DetourLimitExceededException("Pooling onto " + driverId + " would add a detour of " + to_string(detour));
        }
        driver.addPooledRider();
        ride.assignedDriverId = driverId;
        ride.status = RideStatus::MATCHED;
        for (auto& obs : observers) obs->onRideMatched(ride, driver);
        return ride;
    }

    double calculateFare(string rideId) {
        Ride& ride = rides.at(rideId);
        Driver& driver = drivers.at(ride.assignedDriverId);
        double tripDistance = distanceBetween(ride.pickupX, ride.pickupY, ride.dropoffX, ride.dropoffY);
        double fare = BASE_FARE + PER_KM_RATE * tripDistance;
        if (driver.currentRiders > 1) fare *= POOL_DISCOUNT;
        return fare;
    }

    Ride completeRide(string rideId) {
        Ride& ride = rides.at(rideId);
        if (ride.status != RideStatus::MATCHED) {
            throw InvalidRideStateException("Ride " + rideId + " is not matched, cannot be completed");
        }
        Driver& driver = drivers.at(ride.assignedDriverId);
        driver.removeRider();
        ride.status = RideStatus::COMPLETED;
        for (auto& obs : observers) obs->onRideCompleted(ride);
        return ride;
    }
};

