    RideDispatchService service(3.0);
    service.addObserver(make_shared<ConsoleRideObserver>());
    RideIdFactory factory;

    Driver d1("D1", 0.0, 0.0, 2);
    Driver d2("D2", 10.0, 10.0, 2);
    service.addDriver(d1);
    service.addDriver(d2);

    Ride alice = service.requestRide("Alice", 1.0, 1.0, 3.0, 3.0, RideType::POOLED, factory);
    Ride bob = service.requestRide("Bob", 2.0, 2.0, 4.0, 2.0, RideType::POOLED, factory);
    Ride carol = service.requestRide("Carol", 11.0, 11.0, 13.0, 13.0, RideType::POOLED, factory);

    try {
        service.requestRide("Dave", 10.5, 10.5, 12.0, 12.0, RideType::SOLO, factory);
    } catch (NoDriverAvailableException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    cout << "Alice fare: " << service.calculateFare(alice.rideId) << endl;
    cout << "Bob fare: " << service.calculateFare(bob.rideId) << endl;
    cout << "Carol fare: " << service.calculateFare(carol.rideId) << endl;

    Driver d3("D3", 50.0, 50.0, 2);
    service.addDriver(d3);

    Ride eve = service.requestRide("Eve", 50.0, 50.0, 60.0, 60.0, RideType::POOLED, factory);
    try {
        service.poolManually(eve.rideId, "D2", factory);
    } catch (DetourLimitExceededException& e) {
